interface MessageListProps {
    messages: ChatMessage[];
    isLoading: boolean;
    isLive?: boolean;
    liveTranscript?: LiveTranscript;
    onViewImage?: (src: string, alt: string) => void;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isLoading, isLive, liveTranscript, onViewImage }) => {
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [isAtBottom, setIsAtBottom] = useState(true);

    const handleScroll = () => {
        if (!containerRef.current) return;
        const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
        const atBottom = scrollHeight - scrollTop - clientHeight < 50;
        setIsAtBottom(atBottom);
    };

    const scrollToBottom = useCallback((behavior: ScrollBehavior = 'smooth') => {
        messagesEndRef.current?.scrollIntoView({ behavior });
    }, []);

    useEffect(() => {
        if (isAtBottom) {
            scrollToBottom(isLoading ? 'auto' : 'smooth');
        }
    }, [messages, isLoading, liveTranscript, isAtBottom, scrollToBottom]);

    const handleImageLoad = useCallback(() => {
        if (isAtBottom) {
            scrollToBottom('auto');
        }
    }, [isAtBottom, scrollToBottom]);

    if (messages.length === 0 && !isLive) {
        return <WelcomeScreen />;
    }

    return (
        <main 
            className="flex-1 overflow-y-auto p-2 md:p-6" 
            ref={containerRef}
            onScroll={handleScroll}
        >
            <div className="max-w-3xl mx-auto space-y-4 md:space-y-6 pb-4">
                {messages.map((msg, index) => (
                    <Message 
                        key={index} 
                        message={msg} 
                        isLoading={isLoading} 
                        isLast={index === messages.length - 1}
                        onImageLoad={handleImageLoad}
                        onViewImage={onViewImage}
                    />
                ))}

                {isLive && liveTranscript && <LiveTranscriptDisplay transcript={liveTranscript} />}

                <div ref={messagesEndRef} />

                <div className="py-4 text-center opacity-60">
                     <div className="inline-flex items-center gap-2 px-3 py-1 bg-slate-100 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full">
                        <ShieldCheckIcon className="w-3 h-3 text-slate-500" />
                        <span className="text-[10px] text-slate-500 font-mono">
                            MediBrief can make mistakes. Verify important clinical information.
                        </span>
                    </div>
                </div>
            </div>
        </main>
    );
};

export default MessageList;

import React, { useState } from 'react';
import type { ChatMessage } from '../../../types';
import { LinkIcon, DocumentTextIcon, ClipboardIcon, CheckIcon, AlertTriangleIcon, ShieldCheckIcon } from '../../../components/icons';
import MessageContent from './MessageContent';

const isHighCredibilitySource = (uri: string) => {
    try {
        const url = new URL(uri);
        const domain = url.hostname.toLowerCase();
        return domain.endsWith('.gov') || 
               domain.endsWith('.org') || 
               domain.endsWith('.edu') || 
               domain.includes('mayoclinic') ||
               domain.includes('webmd') || 
               domain.includes('medscape') ||
               domain.includes('ncbi') ||
               domain.includes('pubmed');
    } catch {
        return false;
    }
};

const MapPinIcon: React.FC<{className?: string}> = (props) => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" {...props}>
        <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
    </svg>
);

interface MessageProps {
    message: ChatMessage;
    isLoading?: boolean;
    isLast?: boolean;
    onImageLoad?: () => void;
    onViewImage?: (src: string, alt: string) => void;
}

const Message: React.FC<MessageProps> = ({ message, isLoading, isLast, onImageLoad, onViewImage }) => {
    const isModel = message.role === 'model';
    const [isCopied, setIsCopied] = useState(false);

    const isCriticalAlert = isModel && message.content.includes("🛑 CRITICAL SAFETY WARNING");

    const contentToRender = (message.role === 'user' && message.displayContent) 
        ? message.displayContent 
        : message.content;

    const handleCopy = () => {
        navigator.clipboard.writeText(message.content);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    };

    return (
        <div className={`flex flex-col gap-2 group animate-slide-up ${isModel ? 'items-start' : 'items-end'}`}>

            <div className={`flex items-center gap-2 px-1 select-none transition-opacity duration-300 ${isModel ? 'opacity-70' : 'opacity-50'}`}>
                {isModel && <div className={`h-1.5 w-1.5 rounded-full ${isCriticalAlert ? 'bg-red-500 animate-pulse' : 'bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.6)]'}`}></div>}
                <span className={`text-[10px] font-mono uppercase tracking-widest ${isModel ? (isCriticalAlert ? 'text-red-500 font-bold' : 'text-blue-400') : 'text-slate-500'}`}>
                    {isModel ? (isCriticalAlert ? 'CRITICAL_SAFETY_INTERVENTION' : 'CIL_OUTPUT') : 'USER_INPUT'}
                </span>
                {isModel && (
                     <span className="text-[9px] font-mono text-slate-400 border-l border-slate-700 pl-2">
                        {new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                    </span>
                )}
            </div>

            <div className={`
                relative max-w-full md:max-w-3xl p-4 md:p-6 rounded-xl transition-all duration-300 overflow-hidden
                ${isModel 
                    ? isCriticalAlert 
                        ? 'bg-red-950/40 border-l-4 border-red-500 shadow-[0_0_30px_rgba(239,68,68,0.1)] backdrop-blur-md'
                        : 'bg-white/5 dark:bg-[#0f172a]/40 border border-white/10 dark:border-white/5 border-l-4 border-l-blue-500 text-left shadow-lg backdrop-blur-md' 
                    : 'bg-white/10 dark:bg-white/5 border border-white/10 text-left backdrop-blur-md rounded-tr-none'
                }
            `}>

                {isCriticalAlert && (
                    <div className="absolute top-0 right-0 bg-red-600 text-white px-3 py-1 text-[9px] font-bold uppercase tracking-widest rounded-bl-xl shadow-md flex items-center gap-2 z-10">
                        <AlertTriangleIcon className="w-3 h-3" />
                        <span>Protocol Violation</span>
                    </div>
                )}

                {isModel && !isLoading && (
                    <button 
                        onClick={handleCopy}
                        className="absolute top-3 right-3 p-1.5 rounded-md text-slate-400 hover:text-blue-400 hover:bg-white/5 opacity-0 group-hover:opacity-100 transition-all z-20"
                        title="Copy to Clipboard"
                    >
                        {isCopied ? <CheckIcon className="w-3.5 h-3.5 text-green-500" /> : <ClipboardIcon className="w-3.5 h-3.5" />}
                    </button>
                )}

                {message.filePreview && (
                    <div className="mb-4 pb-4 border-b border-slate-200/10">
                         {message.filePreview.type.startsWith('image/') && message.filePreview.url ? (
                             <div className="relative inline-block group/img">
                                <button 
                                    onClick={() => onViewImage?.(message.filePreview!.url!, message.filePreview!.name)}
                                    className="block overflow-hidden border border-white/10 bg-black/50 rounded-lg"
                                >
                                    <img 
                                        src={message.filePreview.url} 
                                        alt={message.filePreview.name} 
                                        onLoad={onImageLoad}
                                        className="max-w-[150px] md:max-w-[200px] max-h-[150px] md:max-h-[200px] object-contain block group-hover/img:scale-105 transition-transform duration-500" 
                                    />
                                </button>
                                <div className="mt-2 flex items-center justify-between text-[10px] font-mono text-slate-400 max-w-[200px]">
                                    <span className="truncate">IMG: {message.filePreview.name}</span>
                                    <span className="text-blue-500 opacity-0 group-hover/img:opacity-100 transition-opacity cursor-pointer font-bold tracking-wider">[EXPAND]</span>
                                </div>
                            </div>
                        ) : (
                             <div className="flex items-center gap-3 p-3 bg-white/5 border border-white/10 rounded-lg w-fit pr-6">
                                <div className="p-2 bg-white/10 rounded-md">
                                    <DocumentTextIcon className="w-5 h-5 text-slate-300" />
                                </div>
                                <div>
                                    <p className="font-mono text-xs font-bold text-slate-200">{message.filePreview.name}</p>
                                    <p className="text-[10px] text-slate-500 uppercase tracking-wide mt-0.5">DATA_INGESTED</p>
                                 </div>
                            </div>
                        )}
                    </div>
                )}

                <MessageContent 
                    content={contentToRender} 
                    role={message.role} 
                    isLoading={!!isLoading} 
                    isLast={!!isLast} 
                />

                {message.sources && message.sources.length > 0 && (
                    <div className="mt-6 pt-4 border-t border-slate-200/10">
                        <div className="flex items-center gap-2 mb-3">
                            <ShieldCheckIcon className="w-3 h-3 text-slate-500" />
                            <span className="text-[10px] font-mono font-bold text-slate-500 uppercase tracking-widest">Verified Sources</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {message.sources.map((source, i) => {
                                if (source.web) {
                                    const isTrusted = isHighCredibilitySource(source.web.uri);
                                    return (
                                        <a key={i} href={source.web.uri} target="_blank" rel="noopener noreferrer"
                                            className={`flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-medium border transition-all rounded-full max-w-full
                                                ${isTrusted 
                                                    ? 'bg-green-500/10 border-green-500/20 text-green-400 hover:bg-green-500/20' 
                                                    : 'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10'
                                                }`}
                                        >
                                            {isTrusted ? <ShieldCheckIcon className="w-3 h-3 text-green-500" /> : <LinkIcon className="w-3 h-3 text-blue-400" />}
                                            <span className="truncate max-w-[200px]">{source.web.title}</span>
                                        </a>
                                    );
                                }
                                if (source.maps) {
                                    return (
                                        <a key={i} href={source.maps.uri} target="_blank" rel="noopener noreferrer"
                                            className="flex items-center gap-1.5 bg-blue-500/10 hover:bg-blue-500/20 border border-blue-500/20 px-3 py-1.5 text-[10px] font-medium text-blue-300 transition-all rounded-full"
                                        >
                                            <MapPinIcon className="w-3 h-3 text-blue-500" />
                                            <span className="truncate max-w-[200px]">{source.maps.title}</span>
                                        </a>
                                    );
                                }
                                return null;
                            })}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Message;

import React, { useMemo } from 'react';
import { parse } from 'marked';
import DOMPurify from 'dompurify';
import BriefingReport from '../../../components/BriefingReport';
import ImageAnalysisReport from '../../../components/ImageAnalysisReport';
import LabReport from '../../../components/LabReport';
import InteractionMatrix from '../../../components/InteractionMatrix';
import ReasoningIndicator from '../../../components/ReasoningIndicator';
import { isJsonBriefing, isImageAnalysis, isLabReport, isInteractionMatrix } from '../../../utils';
import { ChatMode } from '../../../types';

interface MessageContentProps {
    content: string;
    role: 'user' | 'model';
    isLoading: boolean;
    isLast: boolean;
}

const MessageContent: React.FC<MessageContentProps> = ({ content, role, isLoading, isLast }) => {
    const isBriefing = role === 'model' && isJsonBriefing(content);
    const isAnalysis = role === 'model' && isImageAnalysis(content);
    const isLab = role === 'model' && isLabReport(content);
    const isInteraction = role === 'model' && isInteractionMatrix(content);

    const isStreamingJson = useMemo(() => {
        if (role !== 'model' || !isLoading || !isLast) return false;
        const trimmed = content.trim();
        const hasJsonStart = trimmed.includes('```json') || trimmed.startsWith('{');
        return hasJsonStart && !(isBriefing || isAnalysis || isLab || isInteraction);
    }, [content, role, isLoading, isLast, isBriefing, isAnalysis, isLab, isInteraction]);

    const isPlaceholderLoading = role === 'model' && isLast && isLoading && !content.trim();

    const parsedHtml = useMemo(() => {
        if (isStreamingJson || isPlaceholderLoading || isBriefing || isAnalysis || isLab || isInteraction) return null;
        const html = parse(content, { breaks: true, gfm: true }) as string;
        return DOMPurify.sanitize(html);
    }, [content, isStreamingJson, isPlaceholderLoading, isBriefing, isAnalysis, isLab, isInteraction]);

    if (isBriefing) return <BriefingReport content={content} />;
    if (isAnalysis) return <ImageAnalysisReport content={content} />;
    if (isLab) return <LabReport content={content} />;
    if (isInteraction) return <InteractionMatrix content={content} />;

    if (isPlaceholderLoading) {
        return <ReasoningIndicator mode={ChatMode.Standard} />;
    }

    if (isStreamingJson) {
        return (
            <div className="flex flex-col gap-2 p-4 w-full min-w-[300px] animate-pulse bg-slate-50 dark:bg-slate-900/50 border-l-2 border-blue-400">
                <div className="flex items-center gap-2 text-blue-500">
                    <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-mono text-xs uppercase tracking-widest">Synthesizing Clinical Data Structure...</span>
                </div>
                <div className="space-y-2 opacity-50 mt-2">
                    <div className="h-2 bg-slate-200 dark:bg-slate-700 w-3/4 rounded-sm"></div>
                    <div className="h-2 bg-slate-200 dark:bg-slate-700 w-1/2 rounded-sm"></div>
                    <div className="h-2 bg-slate-200 dark:bg-slate-700 w-full rounded-sm"></div>
                </div>
            </div>
        );
    }

    const typographyClasses = `
        prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed font-sans
        prose-headings:font-display prose-headings:font-bold prose-headings:tracking-tight prose-headings:text-slate-900 dark:prose-headings:text-white
        prose-p:my-2 prose-ul:my-2 prose-li:my-0.5
        prose-strong:font-semibold prose-strong:text-slate-900 dark:prose-strong:text-white
        prose-blockquote:bg-red-50 dark:prose-blockquote:bg-red-900/10 
        prose-blockquote:border-l-4 prose-blockquote:border-red-500 
        prose-blockquote:text-red-800 dark:prose-blockquote:text-red-200 
        prose-blockquote:py-3 prose-blockquote:px-4 prose-blockquote:rounded-r-sm
        prose-blockquote:not-italic prose-blockquote:font-medium
        prose-code:font-mono prose-code:text-[11px] prose-code:bg-slate-100 dark:prose-code:bg-slate-800 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded-sm prose-code:text-slate-800 dark:prose-code:text-slate-200
        ${isLoading && isLast ? 'animate-soft-stream' : ''}
    `;

    return (
        <div 
            className={typographyClasses} 
            dangerouslySetInnerHTML={{ __html: parsedHtml || '' }}
        ></div>
    );
};

export default MessageContent;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { ChatMode as ChatModeEnum } from '../../types';
import Header from '../../components/Header';
import MessageList from '../chat/components/MessageList';
import InputBar from '../chat/components/InputBar';
import ImageViewer from '../../components/ImageViewer';
import SidebarRoster from '../patient-roster/SidebarRoster';
import HeadsUpDisplay from '../hud/HeadsUpDisplay';
import ScribeInterface from '../scribe/ScribeInterface';
import CDSSContainer from '../cdss/CDSSContainer';
import BioMetricBackground from './BioMetricBackground';
import { useLiveSession } from '../../hooks/useLiveSession';
import { useFileDragAndDrop } from '../../hooks/useFileDragAndDrop';
import { useChatOrchestrator } from '../chat/hooks/useChatOrchestrator';
import { DocumentTextIcon, ShieldCheckIcon } from '../../components/icons';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useUIStore } from '../ui/UIContext';

// --- IDLE TIMER CONSTANTS ---
const IDLE_TIMEOUT_MS = 5 * 60 * 1000; // 5 Minutes

const MainLayout: React.FC = () => {
    // --- Stores ---
    const { state: patientState, dispatch: patientDispatch, activePatient, activeMessages } = usePatientStore();
    const { uiState, uiDispatch } = useUIStore();

    // --- UI State ---
    const { uploadedFile, setUploadedFile, isDragging, clearFile, dragHandlers } = useFileDragAndDrop();
    const { chatMode, isLoading } = uiState;

    // --- Local UI State ---
    const [userLocation, setUserLocation] = useState<{latitude: number, longitude: number} | undefined>(undefined);
    const [viewingImage, setViewingImage] = useState<{src: string, alt: string} | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);
    const [isLocked, setIsLocked] = useState(false);
    const lastActivityRef = useRef(Date.now());

    // --- IDLE LOCK LOGIC ---
    useEffect(() => {
        const resetTimer = () => {
            lastActivityRef.current = Date.now();
        };

        const checkIdle = () => {
            if (Date.now() - lastActivityRef.current > IDLE_TIMEOUT_MS) {
                setIsLocked(true);
            }
        };

        // Events to track activity
        window.addEventListener('mousemove', resetTimer);
        window.addEventListener('keydown', resetTimer);
        window.addEventListener('touchstart', resetTimer);
        window.addEventListener('scroll', resetTimer);

        // Check interval
        const intervalId = setInterval(checkIdle, 10000); // Check every 10s

        return () => {
            window.removeEventListener('mousemove', resetTimer);
            window.removeEventListener('keydown', resetTimer);
            window.removeEventListener('touchstart', resetTimer);
            window.removeEventListener('scroll', resetTimer);
            clearInterval(intervalId);
        };
    }, []);

    // Responsive Sidebar Check
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) setIsSidebarOpen(false);
            else setIsSidebarOpen(true);
        };
        handleResize(); // Init
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // --- Geolocation ---
    useEffect(() => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => setUserLocation({ latitude: position.coords.latitude, longitude: position.coords.longitude }),
                (err) => console.debug("Location access denied or failed:", err.message)
            );
        }
    }, []);

    // --- Live Session Integration ---
    const handleLiveTurnComplete = useCallback((userInput: string, modelOutput: string) => {
        if (userInput) patientDispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'user', content: userInput } } });
        if (modelOutput) patientDispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'model', content: modelOutput } } });
    }, [patientDispatch]);

    const { isLive, transcript, startSession, stopSession, error: liveError } = useLiveSession(handleLiveTurnComplete);

    useEffect(() => {
        if (liveError) {
            // Log error to chat
            patientDispatch({ type: 'REQUEST_FAILED', payload: liveError });
            // Notify UI (optional, usually handled by toast/component state)
            uiDispatch({ type: 'SET_ERROR', payload: liveError });
        }
    }, [liveError, patientDispatch, uiDispatch]);

    useEffect(() => {
        if (chatMode !== ChatModeEnum.Live && isLive) stopSession();
    }, [chatMode, isLive, stopSession]);

    useEffect(() => {
        if (isLive && chatMode !== ChatModeEnum.Live) uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Live });
    }, [isLive, chatMode, uiDispatch]);

    // --- Chat Orchestrator ---
    const { handleSend, handleStop, handleClearChat, handleExportChat } = useChatOrchestrator({
        messages: activeMessages, 
        activePatientId: activePatient?.id,
        activePatient: activePatient, 
        chatMode: chatMode,
        dispatch: patientDispatch,
        uiDispatch: uiDispatch, // Pass UI dispatch
        uploadedFile,
        setUploadedFile,
        isLive,
        stopSession,
        userLocation,
        clearFile
    });

    const handleViewImage = useCallback((src: string, alt: string) => {
        setViewingImage({ src, alt });
    }, []);

    const toggleLiveSession = useCallback(() => isLive ? stopSession() : startSession(activeMessages), [isLive, stopSession, startSession, activeMessages]);

    // --- LOCK SCREEN UI ---
    if (isLocked) {
        return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-950 text-white relative overflow-hidden">
                <div className="absolute inset-0 bg-grid-pattern opacity-10"></div>
                <div className="z-10 bg-slate-900 border border-slate-700 p-8 rounded-md shadow-2xl max-w-sm w-full text-center technical-border">
                    <ShieldCheckIcon className="w-12 h-12 text-blue-500 mx-auto mb-4 animate-pulse" />
                    <h2 className="text-xl font-display font-bold uppercase tracking-widest mb-2">Session Locked</h2>
                    <p className="text-sm text-slate-400 font-mono mb-6">Security Timeout Triggered (5m)</p>
                    <button 
                        onClick={() => {
                            lastActivityRef.current = Date.now();
                            setIsLocked(false);
                        }}
                        className="w-full py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold uppercase tracking-widest rounded-sm transition-colors"
                    >
                        Resume Session
                    </button>
                </div>
            </div>
        );
    }

    if (!process.env.API_KEY) {
         return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-100 dark:bg-slate-900 text-slate-800 dark:text-slate-200 p-4">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-xl shadow-lg max-w-md text-center">
                    <div className="text-red-500 text-5xl mb-4">⚠️</div>
                    <h1 className="text-xl font-bold mb-2">API Key Missing</h1>
                    <p className="text-slate-600 dark:text-slate-400">Environment variable <code>API_KEY</code> is required.</p>
                </div>
            </div>
         );
    }

    return (
        <div 
            className="flex h-[100dvh] font-sans overflow-hidden relative text-slate-900 dark:text-slate-100"
            {...dragHandlers}
        >
            <BioMetricBackground />

            {isDragging && (
                <div className="absolute inset-0 z-50 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center m-4 rounded-xl animate-fade-in pointer-events-none border-2 border-blue-500/50 shadow-[0_0_50px_rgba(59,130,246,0.3)]">
                    <div className="flex flex-col items-center text-blue-400 animate-pulse">
                        <DocumentTextIcon className="w-20 h-20 mb-6" />
                        <h2 className="text-3xl font-display font-bold tracking-tight">DATA INGESTION PROTOCOL</h2>
                        <p className="font-mono text-sm mt-2 opacity-70 uppercase tracking-widest">Release to initialize scan</p>
                    </div>
                </div>
            )}

            {viewingImage && (
                <ImageViewer 
                    src={viewingImage.src} 
                    alt={viewingImage.alt} 
                    onClose={() => setViewingImage(null)} 
                />
            )}

            <SidebarRoster 
                isOpen={isSidebarOpen} 
                toggle={() => setIsSidebarOpen(!isSidebarOpen)} 
            />

            <div className="flex-1 flex flex-col min-w-0 relative z-10">
                <Header
                    currentMode={chatMode}
                    onModeChange={(mode) => uiDispatch({ type: 'SET_CHAT_MODE', payload: mode })}
                    onClearChat={handleClearChat}
                    onExportChat={handleExportChat}
                    onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                />

                {activePatient && (
                    <HeadsUpDisplay patient={activePatient} />
                )}

                <CDSSContainer />

                {chatMode === ChatModeEnum.Scribe ? (
                    <ScribeInterface />
                ) : (
                    <>
                        <MessageList 
                            messages={activeMessages} 
                            isLoading={isLoading} 
                            isLive={isLive} 
                            liveTranscript={transcript} 
                            onViewImage={handleViewImage}
                        />

                        <InputBar
                            onSend={handleSend}
                            onClearFile={clearFile}
                            setUploadedFile={setUploadedFile}
                            uploadedFile={uploadedFile}
                            isLoading={isLoading}
                            currentMode={chatMode}
                            toggleLiveSession={toggleLiveSession}
                            isLiveSessionActive={isLive}
                            onStop={handleStop}
                        />
                    </>
                )}
            </div>
        </div>
    );
};

export default MainLayout;
